function bind(){document.querySelectorAll(".chip[data-s]").forEach(e=>e.onclick=()=>{const s=F[e.dataset.s],v=e.dataset.s==="len"?+e.dataset.v:e.dataset.v;s.has(v)?s.delete(v):s.add(v);render()});
const b=$("fb");if(b){b.onchange=()=>{F.bolt=b.checked;render()};$("fu").onchange=e=>{F.unk=e.target.checked;render()};$("fm").onchange=e=>{F.max=+e.target.value||0;render()};$("fr").onclick=()=>{F.len.clear();F.cat.clear();F.pay.clear();F.city.clear();F.unk=false;F.bolt=false;F.max=0;F.min=0;F.td=false;render()}}}
